window.openFlyerLightbox = function(imageSrc) {
    console.log("Membuka lightbox untuk:", imageSrc);
    const lightbox = document.getElementById('flyer-lightbox');
    const img = document.getElementById('lightbox-image');
    if (lightbox && img) {
        img.src = imageSrc;
        lightbox.classList.add('active');
        lightbox.style.opacity = '1';
        lightbox.style.visibility = 'visible';
        lightbox.style.pointerEvents = 'auto';
    } else {
        console.error("Elemen lightbox tidak ditemukan di DOM!");
    }
};

window.closeFlyerLightbox = function() {
    const lightbox = document.getElementById('flyer-lightbox');
    if (lightbox) {
        lightbox.classList.remove('active');
        lightbox.style.opacity = '0';
        lightbox.style.visibility = 'hidden';
        lightbox.style.pointerEvents = 'none';
    }
};

