window.openFlyerLightbox = function(imageSrc) {
    let lightbox = document.getElementById('flyer-lightbox');
    // Buat lightbox on-the-fly jika tidak ada di DOM
    if (!lightbox) {
        lightbox = document.createElement('div');
        lightbox.id = 'flyer-lightbox';
        lightbox.onclick = function(e) { if (e.target === lightbox) window.closeFlyerLightbox(); };
        lightbox.innerHTML = `
            <div id="lightbox-inner" onclick="event.stopPropagation()" style="position:relative; max-width:90vw; max-height:90vh; display:flex; align-items:center; justify-content:center;">
                <div onclick="window.closeFlyerLightbox()" style="position:absolute;top:-16px;right:-16px;width:36px;height:36px;background:rgba(255,255,255,0.9);border-radius:50%;display:flex;align-items:center;justify-content:center;cursor:pointer;font-size:22px;font-weight:bold;color:#333;z-index:10;box-shadow:0 2px 8px rgba(0,0,0,0.3);">&times;</div>
