// ==================== HAPUS JADWAL TRAINING ====================
window.deleteTraining = function(id) {
    const trainings = JSON.parse(localStorage.getItem('pa_trainings')) || [];
    const t = trainings.find(x => x.id === id);
    if (!t) return;

    if (!confirm(`⚠️ Yakin ingin menghapus jadwal training:\n"${t.title}"?\n\nTindakan ini tidak dapat dibatalkan.`)) return;

    const updated = trainings.filter(x => x.id !== id);
    localStorage.setItem('pa_trainings', JSON.stringify(updated));
    alert('Jadwal training berhasil dihapus.');
    renderTrainerTrainings();
};

